    'Emergency messages': { fr: 'Messages d’urgence', es: 'Mensajes de emergencia', hi: 'आपातकालीन संदेश' },
    'Stop all text messages': { fr: 'Arrêter tous les textos', es: 'Detener todos los mensajes de texto', hi: 'सभी टेक्स्ट संदेश बंद करें' },
    'Tell me when my child is signed in or out, and who by.': { fr: 'Me prévenir quand mon enfant arrive ou part, et par qui.', es: 'Avisarme cuando se registre la entrada o salida de mi hijo, y quién lo hizo.', hi: 'मेरे बच्चे का साइन इन या आउट होने पर, और किसने किया, मुझे बताएँ।' },
    'Text': { fr: 'Texto', es: 'Mensaje de texto', hi: 'टेक्स्ट' },
    'In-app': { fr: 'Dans l’application', es: 'En la aplicación', hi: 'ऐप में' },
    'New chats and alerts only show a badge.': { fr: 'Les nouveaux clavardages et alertes affichent seulement une pastille.', es: 'Los chats y alertas nuevos solo muestran un distintivo.', hi: 'नई चैट और अलर्ट केवल बैज दिखाते हैं।' },
    'New chats and alerts take over the screen with sound.': { fr: 'Les nouveaux clavardages et alertes s’affichent en plein écran avec un son.', es: 'Los chats y alertas nuevos ocupan la pantalla con sonido.', hi: 'नई चैट और अलर्ट ध्वनि के साथ पूरी स्क्रीन पर दिखते हैं।' },
    'Send test notification': { fr: 'Envoyer une notification d’essai', es: 'Enviar notificación de prueba', hi: 'परीक्षण सूचना भेजें' },
    'Test urgent alert': { fr: 'Tester une alerte urgente', es: 'Probar alerta urgente', hi: 'तत्काल अलर्ट का परीक्षण' },
    'No registered devices yet. Open the app once and allow notifications, then retry.': { fr: 'Aucun appareil enregistré. Ouvrez l’application une fois et autorisez les notifications, puis réessayez.', es: 'Aún no hay dispositivos registrados. Abra la aplicación una vez, permita las notificaciones y vuelva a intentarlo.', hi: 'अभी कोई डिवाइस पंजीकृत नहीं। ऐप एक बार खोलें और सूचनाओं की अनुमति दें, फिर दोबारा कोशिश करें।' },
    'A non-urgent announcement by phone.': { fr: 'Une annonce non urgente par téléphone.', es: 'Un anuncio no urgente por teléfono.', hi: 'फ़ोन पर एक गैर-ज़रूरी घोषणा।' },
    'An urgent call about your centre.': { fr: 'Un appel urgent au sujet de votre centre.', es: 'Una llamada urgente sobre su centro.', hi: 'आपके केंद्र के बारे में एक तत्काल कॉल।' },
    'Phone calls': { fr: 'Appels téléphoniques', es: 'Llamadas telefónicas', hi: 'फ़ोन कॉल' },
    'Don\'t phone me at all': { fr: 'Ne jamais m’appeler', es: 'No llamarme nunca', hi: 'मुझे बिल्कुल फ़ोन न करें' },
    'Add a mobile number to your profile to receive texts and calls.': { fr: 'Ajoutez un numéro de cellulaire à votre profil pour recevoir des textos et des appels.', es: 'Añada un número móvil a su perfil para recibir mensajes y llamadas.', hi: 'टेक्स्ट और कॉल पाने के लिए अपनी प्रोफ़ाइल में मोबाइल नंबर जोड़ें।' },
    'Agree to receive texts': { fr: 'J’accepte de recevoir des textos', es: 'Acepto recibir mensajes de texto', hi: 'टेक्स्ट पाने के लिए सहमत हों' },
