    'Could not turn text messages on.': { fr: 'Impossible d’activer les textos.', es: 'No se pudieron activar los mensajes de texto.', hi: 'टेक्स्ट संदेश चालू नहीं हो सके।' },
    'We have sent you a confirmation text.': { fr: 'Nous vous avons envoyé un texto de confirmation.', es: 'Le hemos enviado un mensaje de confirmación.', hi: 'हमने आपको एक पुष्टि टेक्स्ट भेजा है।' },
    'You will not receive any more texts.': { fr: 'Vous ne recevrez plus de textos.', es: 'No recibirá más mensajes de texto.', hi: 'अब आपको कोई टेक्स्ट नहीं मिलेगा।' },
    'You have not agreed to receive texts, so none of these are sent to you yet.': { fr: 'Vous n’avez pas accepté de recevoir des textos; aucun ne vous est donc encore envoyé.', es: 'No ha aceptado recibir mensajes de texto, así que todavía no se le envía ninguno.', hi: 'आपने टेक्स्ट पाने की सहमति नहीं दी है, इसलिए अभी इनमें से कोई नहीं भेजा जाता।' },
    'Your agency does not place announcement calls at the moment. Your choices here are kept for when it does.': { fr: 'Votre agence ne fait pas d’appels d’annonce pour l’instant. Vos choix sont conservés pour le jour où elle en fera.', es: 'Su agencia no hace llamadas de anuncios por ahora. Sus opciones se guardan para cuando las haga.', hi: 'आपकी एजेंसी अभी घोषणा कॉल नहीं करती। आपकी पसंद तब के लिए रखी गई है जब वह करेगी।' },
    'Save preferences': { fr: 'Enregistrer les préférences', es: 'Guardar preferencias', hi: 'प्राथमिकताएँ सहेजें' },
